const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([104.238631, 40.923221]);
  const aoi = point.buffer(50000); // 50km radius

  const dateRange2019 = ee.DateRange('2019-02-01', '2019-03-01');
  const dateRange2020 = ee.DateRange('2020-02-01', '2020-03-01');

  // 2. Data Acquisition & Processing Function
  const getMonthlyAerosol = function(dateRange, aoi) {
    const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_AER_AI')
      .filterBounds(aoi)
      .filterDate(dateRange)
      .select(['absorbing_aerosol_index', 'qa_value']);

    // Immediately check if the collection is empty
    const size = collection.size().getInfo();
    if (size === 0) {
      return {
        image: null,
        size: 0
      };
    }

    // Create a median composite and apply a quality mask
    const image = collection.median();
    const qaMask = image.select('qa_value').gt(0.75);
    const maskedImage = image.select('absorbing_aerosol_index').updateMask(qaMask);

    return {
      image: maskedImage,
      size: size
    };
  };

  // 3. Calculation for each year
  const data2019 = getMonthlyAerosol(dateRange2019, aoi);
  const data2020 = getMonthlyAerosol(dateRange2020, aoi);

  if (data2019.size === 0 || data2020.size === 0) {
    console.log(`Image count 2019: ${data2019.size}`);
    console.log(`Image count 2020: ${data2020.size}`);
    console.log('No images found for one or both periods.');
    console.log('C1');
    return;
  }
  console.log(`Image count 2019: ${data2019.size}`);
  console.log(`Image count 2020: ${data2020.size}`);

  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats2019 = data2019.image.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  const stats2020 = data2020.image.reduceRegion({
    reducer: reducer,
    geometry: aoi,
    scale: 3000,
    maxPixels: 1e9
  });

  // Using evaluate to fetch results concurrently
  const results = await new Promise((resolve, reject) => {
    ee.Dictionary({
      '2019': stats2019,
      '2020': stats2020
    }).evaluate(resolve);
  });

  const mean2019 = results['2019']['absorbing_aerosol_index_mean'];
  const count2019 = results['2019']['absorbing_aerosol_index_count'];
  const mean2020 = results['2020']['absorbing_aerosol_index_mean'];
  const count2020 = results['2020']['absorbing_aerosol_index_count'];

  // 4. Validation & Final Answer
  if (count2019 === 0 || count2020 === 0) {
    console.log(`Valid pixels 2019: ${count2019}`);
    console.log(`Valid pixels 2020: ${count2020}`);
    console.log('No valid pixels after cloud/quality masking.');
    console.log('C2');
    return;
  }

  if (mean2019 === null || mean2020 === null) {
    console.log(`Mean AI 2019: ${mean2019}`);
    console.log(`Mean AI 2020: ${mean2020}`);
    console.log('Calculation failed, result is null.');
    console.log('C3');
    return;
  }

  console.log(`Feb 2019 Mean Aerosol Index: ${mean2019.toFixed(4)} (Pixels: ${count2019})`);
  console.log(`Feb 2020 Mean Aerosol Index: ${mean2020.toFixed(4)} (Pixels: ${count2020})`);

  if (mean2020 > mean2019) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error('An error occurred during Earth Engine initialization or analysis.');
    console.error(e);
    console.log('D');
  }
}

initEE();
